package ama.api;
import ama.contract.IdentityContracts.*;import ama.transcript.*;import ama.access.MeetingAccess;import ama.db.TransactionRunner;import jakarta.servlet.http.*;import java.io.*;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/meetings/{meetingId}/minutes") final class MinutesSavedController {
 private final MinutesConfiguration.Runtime runtime;private final JdbcMinutesCommandReceipts receipts;private final TransactionRunner tx;private final MeetingAccess access;
 MinutesSavedController(MinutesConfiguration.Runtime runtime,JdbcMinutesCommandReceipts receipts,TransactionRunner tx,MeetingAccess access){this.runtime=runtime;this.receipts=receipts;this.tx=tx;this.access=access;}
 @GetMapping ResponseEntity<byte[]> current(@PathVariable String meetingId,HttpServletRequest request)throws IOException{return json(queries(request,meetingId,false).current(actor(request),meetingId));}
 @GetMapping("/history") ResponseEntity<byte[]> bodies(@PathVariable String meetingId,@RequestParam(defaultValue="20") int limit,@RequestParam(required=false) String beforeRevisionToken,HttpServletRequest request)throws IOException{return json(queries(request,meetingId,true).history(actor(request),meetingId,true,limit,beforeRevisionToken));}
 @GetMapping("/element-sets") ResponseEntity<byte[]> sets(@PathVariable String meetingId,@RequestParam(defaultValue="20") int limit,@RequestParam(required=false) String beforeRevisionToken,HttpServletRequest request)throws IOException{return json(queries(request,meetingId,true).history(actor(request),meetingId,false,limit,beforeRevisionToken));}
 @GetMapping("/revisions/{id}") ResponseEntity<byte[]> body(@PathVariable String meetingId,@PathVariable String id,HttpServletRequest request)throws IOException{return json(queries(request,meetingId,true).detail(actor(request),meetingId,id,true));}
 @GetMapping("/element-sets/{id}") ResponseEntity<byte[]> set(@PathVariable String meetingId,@PathVariable String id,HttpServletRequest request)throws IOException{return json(queries(request,meetingId,true).detail(actor(request),meetingId,id,false));}
 @GetMapping("/settings") ResponseEntity<byte[]> settings(@PathVariable String meetingId,HttpServletRequest request)throws IOException{return json(queries(request,meetingId,true).settings(actor(request),meetingId));}
 @GetMapping("/readiness") ResponseEntity<byte[]> readiness(@PathVariable String meetingId,HttpServletRequest request)throws IOException{return json(queries(request,meetingId,true).readiness(actor(request),meetingId));}
 @GetMapping("/reviews") ResponseEntity<byte[]> reviews(@PathVariable String meetingId,@RequestParam String targetKind,@RequestParam String targetId,@RequestParam(defaultValue="20") int limit,@RequestParam(required=false) String beforeReviewNoToken,HttpServletRequest request)throws IOException{return json(queries(request,meetingId,true).reviews(actor(request),meetingId,targetKind,targetId,limit,beforeReviewNoToken));}
 @GetMapping("/reviews/{id}") ResponseEntity<byte[]> review(@PathVariable String meetingId,@PathVariable String id,HttpServletRequest request)throws IOException{return json(queries(request,meetingId,true).review(actor(request),meetingId,id));}
 @GetMapping("/sources/{id}") ResponseEntity<byte[]> source(@PathVariable String meetingId,@PathVariable String id,@RequestParam String targetKind,@RequestParam String targetId,HttpServletRequest request)throws IOException{return json(queries(request,meetingId,false).source(actor(request),meetingId,id,targetKind,targetId,null,null));}
 @GetMapping("/revisions/{revision}/sources/{id}") ResponseEntity<byte[]> bodySource(@PathVariable String meetingId,@PathVariable String revision,@PathVariable String id,HttpServletRequest request)throws IOException{return json(queries(request,meetingId,true).source(actor(request),meetingId,id,null,null,revision,null));}
 @GetMapping("/element-sets/{set}/sources/{id}") ResponseEntity<byte[]> setSource(@PathVariable String meetingId,@PathVariable String set,@PathVariable String id,HttpServletRequest request)throws IOException{return json(queries(request,meetingId,true).source(actor(request),meetingId,id,null,null,null,set));}
 @PostMapping("/command-discovery") ResponseEntity<byte[]> discovery(@PathVariable String meetingId,HttpServletRequest request)throws IOException{var body=MinutesSavedWire.discovery(request);return json(receipts.discover(actor(request),meetingId,body.get("operation"),body.get("key")));}
 @PutMapping("/body") ResponseEntity<byte[]> saveBody(@PathVariable String meetingId,HttpServletRequest request)throws IOException{return command(meetingId,null,"MINUTES_BODY_SAVE",request);}
 @PutMapping("/elements/{id}") ResponseEntity<byte[]> saveElement(@PathVariable String meetingId,@PathVariable String id,HttpServletRequest request)throws IOException{return command(meetingId,id,"MINUTES_ELEMENT_EDIT",request);}
 @PutMapping("/elements/{id}/action-fields") ResponseEntity<byte[]> action(@PathVariable String meetingId,@PathVariable String id,HttpServletRequest request)throws IOException{return command(meetingId,id,"MINUTES_ACTION_FIELDS",request);}
 @PostMapping("/elements/{id}/open-question") ResponseEntity<byte[]> question(@PathVariable String meetingId,@PathVariable String id,HttpServletRequest request)throws IOException{return command(meetingId,id,"MINUTES_OPEN_QUESTION",request);}
 @PostMapping("/body-restorations") ResponseEntity<byte[]> restoreBody(@PathVariable String meetingId,HttpServletRequest request)throws IOException{return command(meetingId,null,"MINUTES_BODY_RESTORE",request);}
 @PostMapping("/element-set-restorations") ResponseEntity<byte[]> restoreSet(@PathVariable String meetingId,HttpServletRequest request)throws IOException{return command(meetingId,null,"MINUTES_SET_RESTORE",request);}
 @PutMapping("/settings/template") ResponseEntity<byte[]> template(@PathVariable String meetingId,HttpServletRequest request)throws IOException{return command(meetingId,null,"MINUTES_TEMPLATE",request);}
 @PutMapping("/settings/exclusions") ResponseEntity<byte[]> exclusions(@PathVariable String meetingId,HttpServletRequest request)throws IOException{return command(meetingId,null,"MINUTES_EXCLUSIONS",request);}
 @PostMapping("/candidates/{id}/adoptions") ResponseEntity<byte[]> adopt(@PathVariable String meetingId,@PathVariable String id,HttpServletRequest request)throws IOException{return command(meetingId,id,"MINUTES_ADOPT",request);}
 @PostMapping("/candidates/{id}/rejections") ResponseEntity<byte[]> reject(@PathVariable String meetingId,@PathVariable String id,HttpServletRequest request)throws IOException{return command(meetingId,id,"MINUTES_REJECT",request);}
 @PostMapping("/candidates/{id}/disposals") ResponseEntity<byte[]> dispose(@PathVariable String meetingId,@PathVariable String id,HttpServletRequest request)throws IOException{return command(meetingId,id,"MINUTES_DISPOSE",request);}
 @PostMapping("/reviews") ResponseEntity<byte[]> createReview(@PathVariable String meetingId,HttpServletRequest request)throws IOException{return command(meetingId,null,"MINUTES_REVIEW",request);}
 private ResponseEntity<byte[]> command(String meeting,String selected,String operation,HttpServletRequest request)throws IOException{var body=MinutesSavedWire.command(request,operation,selected);var replay=receipts.lookup(actor(request),meeting,operation,key(request),body.expected(),body.semantics());if(replay.isPresent())return json(replay.orElseThrow());throw new ama.contract.TranscriptContracts.Failure(503,"TASK11_NOT_INSTALLED");}
 private JdbcMinutesSavedQueries queries(HttpServletRequest request,String meeting,boolean owner){ama.contract.MinutesContracts.uuid(meeting);if(runtime.saved()!=null)return runtime.saved();tx.required(()->{access.require(access.lock(actor(request),meeting),owner?MeetingAccess.Action.EDIT:MeetingAccess.Action.READ);return null;});throw new ama.contract.TranscriptContracts.Failure(503,"MINUTES_UNAVAILABLE");}
 private static String key(HttpServletRequest request){var values=Collections.list(request.getHeaders("Idempotency-Key"));if(values.size()!=1)throw new IllegalArgumentException("One idempotency key required");JdbcProcessingIntake.key(values.getFirst());return values.getFirst();}
 private static Actor actor(HttpServletRequest request){return ((ResolvedSession)request.getAttribute(SessionSecurityFilter.SESSION)).actor();}
 private ResponseEntity<byte[]> json(Object value)throws IOException{try{return ResponseEntity.ok().contentType(MediaType.APPLICATION_JSON).header("Cache-Control","private, no-store").body(TranscriptWire.response(value,runtime.responseBytes()));}catch(ama.contract.TranscriptContracts.Failure failure){if("RESPONSE_BUDGET_EXCEEDED".equals(failure.code()))throw new ama.contract.TranscriptContracts.Failure(413,"REQUEST_TOO_LARGE");throw failure;}}
}
